// ===== 설정 (여기만 수정하세요) =====
return [{ json: {
  APP_ID: 'com.lgeha.nuts',   // LG ThinQ 구글플레이 앱 ID
  LANG: 'ko', COUNTRY: 'kr',
  MAX_PAGES: 30,              // 1페이지 = 최신 리뷰 최대 150개 → 30페이지 ≈ 4,500개
  KEEP_STARS: [1, 2, 3],      // 남길 별점
  token: null, page: 0,
} }];

// 다음 페이지 요청 본문 만들기 (구글플레이 웹페이지가 쓰는 요청 형식)
const cfg = $('설정').first().json;
const s = $input.first().json;               // 처음엔 설정, 이후엔 '페이지 정리'에서 돌아온 값
const inner = JSON.stringify([null, null, [2, 2, [150, null, s.token || null], null, []], [cfg.APP_ID, 7]]);
return [{ json: { page: s.page || 0, token: s.token || null, freq: JSON.stringify([[['UsvDTd', inner, null, 'generic']]]) } }];

// 응답 1페이지 → 리뷰 목록 + 다음 페이지 토큰
const cfg = $('설정').first().json;
const prev = $('요청 준비').first().json;
const text = String($input.first().json.data || '');
let inner = null, error = '';
try { const outer = JSON.parse(text.substring(5)); inner = outer && outer[0] && outer[0][2] ? JSON.parse(outer[0][2]) : null; }
catch (e) { error = '응답 해석 실패: ' + text.slice(0, 120); }
const pick = (a, p) => p.reduce((x, k) => (x == null ? undefined : x[k]), a);
const toDate = d => d ? new Date(Number(String(d[0]) + String(d[1] || '000').slice(0, 3))).toISOString().slice(0, 10) : '';
const reviews = ((inner && inner[0]) || []).map(r => ({ id: r[0], score: r[2], text: r[4] || '', date: toDate(r[5]),
  thumbsUp: r[6] || 0, version: r[10] || '', replied: pick(r, [7, 1]) ? 'Y' : '' }))
  .filter(r => cfg.KEEP_STARS.includes(r.score));     // 별점 1·2·3만 보관 (메모리 절약)
const token = pick(inner, [1, 1]) || null;
const page = prev.page + 1;
return [{ json: { page, token, more: !!token && page < cfg.MAX_PAGES && !error, kept: reviews.length, error, reviews } }];

// 모든 페이지 결과 합치기 (반복 실행된 '페이지 정리' 노드의 각 회차 결과를 모음)
const all = [], seen = new Set();
let runs = 0, lastError = '';
for (let run = 0; run < 200; run++) {
  let items;
  try { items = $('페이지 정리').all(0, run); } catch (e) { break; }
  if (!items || !items.length) break;
  runs++;
  for (const it of items) {
    if (it.json.error) lastError = it.json.error;
    for (const r of (it.json.reviews || [])) if (!seen.has(r.id)) { seen.add(r.id); all.push(r); }
  }
}
return [{ json: { reviews: all, keepStars: $('설정').first().json.KEEP_STARS, pagesRead: runs, lastError } }];

// 별점 1·2·3 리뷰 → 문제 유형·제품·판단 어려움 키워드 태깅
const { reviews, keepStars } = $input.first().json;
const TOPICS = {
  '기기 연결·등록': /연결|등록|페어링|와이파이|wi-?fi|공유기|네트워크|오프라인|인식\s*(이\s*)?안|제품\s*추가/i,
  '원격제어 안 됨': /원격|제어|조작|작동\s*(이\s*)?안|반응\s*(이\s*)?없|안\s*켜|안\s*꺼|켜지지|꺼지지/,
  '앱 먹통·로딩·서버': /먹통|로딩|튕|멈춰|멈춤|서버|접속|강제\s*종료|안\s*열|오류|에러|렉|버벅|느려|느림/,
  '로그인·계정': /로그인|계정|인증|비밀번호|비번|탈퇴|회원/,
  '업데이트 후 문제': /업데이트|업뎃|버전|개편|바뀐\s*후|바뀌고|예전이\s*(더|나)/,
  '알림': /알림|푸시|알람/,
  '스마트진단': /스마트\s*진단|자가\s*진단|진단/,
  '자동화·루틴·예약': /루틴|자동화|예약|스케줄|타이머/,
  '설정 임의 변경': /(마음|멋)대로|혼자\s*(바뀌|켜|꺼)|저절로|임의/,
  'UI·사용성': /불편|복잡|찾기\s*(힘|어려)|어디(에|서)|메뉴|ui|ux|디자인|직관/i,
  '1:1 문의·고객센터': /1\s*:\s*1|문의|고객\s*센터|상담|답변|as|a\/s|서비스\s*센터/i,
  '기능 삭제·축소': /기능\s*(이\s*)?(없어|삭제|빠|사라)|없어졌|사라졌|뺐/,
  '광고·불필요 기능': /광고|쓸데\s*없|불필요|이벤트|쇼핑/,
  '권한·배터리·위치': /권한|배터리|위치|블루투스/,
};
const PRODUCTS = { '에어컨': /에어컨|에어콘|휘센|냉방/, '세탁기·건조기': /세탁기|건조기|워시|스타일러/, '냉장고': /냉장고|김치/,
  '식기세척기': /식세기|식기세척/, '공기청정기·제습기': /공기\s*청정|퓨리케어|제습기|가습기/, '로봇청소기·청소기': /청소기|코드제로/,
  'TV': /tv|티비|텔레비전/i, '오븐·인덕션': /오븐|인덕션|전자레인지/ };
const CAUSE = /왜\s*(그런|이러|이렇|안|자꾸|계속)|원인|뭐가\s*문제|무슨\s*문제|이유가|고장\s*인가|고장인지|정상\s*인가|정상인지|모르겠|저만\s*그런/;
const ACTION = /어떻게\s*(해야|하면|하나요|하죠)|어떡하|어쩌라|해야\s*(하나요|할까|되나|되나요)|방법\s*(이|좀)?\s*(있|알려|없)|해결\s*(방법|이\s*안|못)|알려\s*주세요/;
const TRIED = /해\s*봤|해봤|했는데|했는데도|했지만|그래도|여전히|그대로|재설치|삭제\s*후|지웠다|초기화|리셋|껐다\s*켜|재부팅|다시\s*(등록|깔)/;
const Y = b => b ? 'Y' : '';
const rows = [];
for (const r of reviews) {
  if (!keepStars.includes(r.score)) continue;
  const t = String(r.text).replace(/\s+/g, ' ').trim();
  if (t.length < 3) continue;
  const topics = Object.entries(TOPICS).filter(([, re]) => re.test(t)).map(([k]) => k);
  const prods = Object.entries(PRODUCTS).filter(([, re]) => re.test(t)).map(([k]) => k);
  rows.push({ '별점': r.score, '작성일': r.date, '앱버전': r.version, '리뷰내용': t, '도움돼요': r.thumbsUp, 'LG답변여부': r.replied,
    '문제유형': topics.join(', ') || '(분류 안 됨)', '언급제품': prods.join(', '), '에어컨언급': Y(prods.includes('에어컨')),
    '원인모름': Y(CAUSE.test(t)), '다음행동모름': Y(ACTION.test(t)), '이미시도한조치': Y(TRIED.test(t)), '리뷰ID': r.id });
}
rows.sort((a, b) => a['별점'] - b['별점'] || String(b['작성일']).localeCompare(String(a['작성일'])));
return rows.map(r => ({ json: r }));

// 별점별 키워드 집계표: (1) 문제 유형별 건수·비율 (2) 자주 나온 단어 TOP 30
const rows = $input.all().map(i => i.json);
const stars = [1, 2, 3];
const by = s => rows.filter(r => r['별점'] === s);
const out = [];
// (1) 문제 유형
const topics = [...new Set(rows.flatMap(r => r['문제유형'].split(', ')))];
const tCount = (list, t) => list.filter(r => r['문제유형'].split(', ').includes(t)).length;
const pct = (a, b) => b ? Math.round(a / b * 1000) / 10 + '%' : '-';
const ranked = topics.map(t => ({ t, n: tCount(rows, t) })).sort((a, b) => b.n - a.n);
out.push({ 구분: '전체 리뷰 수', 항목: '', '1점': by(1).length, '2점': by(2).length, '3점': by(3).length, 합계: rows.length });
for (const { t, n } of ranked) {
  const row = { 구분: '문제 유형', 항목: t };
  for (const s of stars) { const L = by(s); row[s + '점'] = `${tCount(L, t)} (${pct(tCount(L, t), L.length)})`; }
  row['합계'] = `${n} (${pct(n, rows.length)})`; out.push(row);
}
for (const [k, label] of [['원인모름', '원인 모름 신호'], ['다음행동모름', '다음 행동 모름 신호'], ['이미시도한조치', '이미 시도한 조치'], ['에어컨언급', '에어컨 언급']]) {
  const row = { 구분: '신호', 항목: label };
  for (const s of stars) { const L = by(s); const c = L.filter(r => r[k] === 'Y').length; row[s + '점'] = `${c} (${pct(c, L.length)})`; }
  const c = rows.filter(r => r[k] === 'Y').length; row['합계'] = `${c} (${pct(c, rows.length)})`; out.push(row);
}
// (2) 자주 나온 단어 (조사 떼고, 불용어 제외)
const STOP = new Set('앱 어플 엘지 lg thinq 씽큐 너무 진짜 정말 그냥 계속 자꾸 이거 이게 그리고 근데 하는 하고 해서 있는 없는 되는 안되 안됨 합니다 하네요 해요 있어요 없어요 같아요 좀 더 다시 제품 사용 사용중 이제 지금 매번 항상 다른 그런 이런 저런 하나 때문 때문에 수가 것도 것이 것은 것을 거의 많이 별로 제발 빨리 왜 뭐 이건 저는 제가 나는 내가'.split(' '));
const strip = w => w.replace(/(으로|에서|에게|까지|부터|이랑|하고|이나|이고|이라|입니다|습니다|해요|네요|어요|아요|은|는|이|가|을|를|에|도|로|만|의|과|와|요|고)$/,'');
const words = list => { const m = new Map(); for (const r of list) for (let w of r['리뷰내용'].toLowerCase().split(/[^0-9a-z가-힣]+/)) {
  w = strip(w); if (w.length < 2 || STOP.has(w) || /^\d+$/.test(w)) continue; m.set(w, (m.get(w) || 0) + 1); } return [...m].sort((a, b) => b[1] - a[1]).slice(0, 30); };
const top = Object.fromEntries(stars.map(s => [s, words(by(s))]));
for (let i = 0; i < 30; i++) {
  const row = { 구분: '자주 나온 단어', 항목: `${i + 1}위` };
  for (const s of stars) { const w = top[s][i]; row[s + '점'] = w ? `${w[0]} (${w[1]})` : ''; }
  row['합계'] = ''; out.push(row);
}
return out.map(r => ({ json: r }));
